package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtils_gcd_TriageGen2Test {

    @Test
    public void testGcdBasic() {
        assertEquals(6, MathUtils.gcd(12, 18));
        assertEquals(1, MathUtils.gcd(7, 13));
        assertEquals(5, MathUtils.gcd(25, 5));
        assertEquals(10, MathUtils.gcd(10, 10));
    }

    @Test
    public void testGcdWithNegativeNumbers() {
        // The implementation converts u and v to negative, 
        // so gcd(p, q) should behave like gcd(|p|, |q|)
        assertEquals(6, MathUtils.gcd(-12, 18));
        assertEquals(6, MathUtils.gcd(12, -18));
        assertEquals(6, MathUtils.gcd(-12, -18));
    }

    @Test
    public void testGcdWithZero() {
        // if (u == 0 || v == 0) return Math.abs(u) + Math.abs(v)
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(0, MathUtils.gcd(0, 0));
        assertEquals(10, MathUtils.gcd(-10, 0));
        assertEquals(10, MathUtils.gcd(0, -10));
    }

    @Test(expected = RuntimeException.class)
    public void testGcdOverflowWithMinInt() {
        // if ((u == 0 || v == 0) && (u == Integer.MIN_VALUE || v == Integer.MIN_VALUE)) 
        // throws exception
        MathUtils.gcd(Integer.MIN_VALUE, 0);
    }

    @Test(expected = RuntimeException.class)
    public void testGcdOverflowWithMinIntSecondParam() {
        MathUtils.gcd(0, Integer.MIN_VALUE);
    }

    @Test
    public void testGcdPowerOfTwo() {
        // Tests the k logic (B1)
        assertEquals(4, MathUtils.gcd(4, 8));
        assertEquals(8, MathUtils.gcd(16, 8));
        assertEquals(1, MathUtils.gcd(1, 3));
    }

    @Test
    public void testGcdOddAndEven() {
        // Tests B2/B3 logic: t = ((u & 1) == 1) ? v : -(u / 2)
        // Case 1: u is odd
        assertEquals(3, MathUtils.gcd(3, 6));
        // Case 2: u is even (after casting out twos)
        assertEquals(2, MathUtils.gcd(4, 6));
    }

    @Test
    public void testGcdLargeNumbers() {
        assertEquals(1, MathUtils.gcd(104729, 104723)); // Two primes
        assertEquals(123, MathUtils.gcd(12345, 123));
    }

    @Test
    public void testGcdEdgeCases() {
        // Testing the loop B6/B3 logic where t = (v - u) / 2
        // p, q such that they are not powers of 2 and require several iterations
        assertEquals(7, MathUtils.gcd(49, 77));
        assertEquals(1, MathUtils.gcd(Integer.MAX_VALUE, Integer.MAX_VALUE - 2));
    }
}
